B.Wa=s(["I work at Sakura Company.","Sakura Company is closed.","I am going to Sakura Company."],t.s)
B.a0E=new A.dp("encounter_workplace","Where do you work?","First Encounters","I can state my workplace and ask where another person works.",B.im,B.e9,"\u3055\u304f\u3089\u4f1a\u793e\u3067\u50cd\u3044\u3066\u3044\u307e\u3059\u3002","Sakura-gaisha de hataraite imasu.","I work at Sakura Company.",B.Wa,0,"Japanese introductions often include company or group affiliation before job title.","Home office","\ud83e\udeb4","encounter_greeting")
B.VR=s(["When is the station open?","How much is the train?","Where is the station?"],t.s)
B.a0K=new A.dp("directions_station","Find the station","Getting Directions","I can ask where a station or landmark is.",B.im,B.e9,"\u3059\u307f\u307e\u305b\u3093\u3001\u99c5\u306f\u3069\u3053\u3067\u3059\u304b\u3002","Sumimasen, eki wa doko desu ka?","Excuse me, where is the station?",B.VR,2,"\u3059\u307f\u307e\u305b\u3093 gently gets attention and also communicates consideration for the interruption.","Tiny station","\ud83d\ude89","encounter_workplace")
B.eQ=new A.ry(2,"dailyLife")
B.p4=new A.cm([B.h0,B.ea,B.iF],t.H4)
B.X8=s(["One ticket to Kyoto, please.","Which platform is Kyoto?","I came from Kyoto."],t.s)
B.a0J=new A.dp("transport_ticket","Buy a train ticket","Transportation","I can ask for one ticket to a destination.",B.eQ,B.p4,"\u4eac\u90fd\u307e\u3067\u4e00\u679a\u304a\u9858\u3044\u3057\u307e\u3059\u3002","Kyouto made ichimai onegaishimasu.","One ticket to Kyoto, please.",B.X8,0,"\u679a is the counter used for flat items such as paper tickets.","Railway clock","\ud83d\udd70\ufe0f","directions_station")
B.Xa=s(["What is this?","How much is this?","May I try this?"],t.s)
B.a0x=new A.dp("shopping_price","Ask the price","Shopping","I can ask the price and understand a simple answer.",B.eQ,B.p4,"\u3053\u308c\u306f\u3044\u304f\u3089\u3067\u3059\u304b\u3002","Kore wa ikura desu ka?","How much is this?",B.Xa,1,"Place cash or cards on the payment tray when one is provided rather than handing them directly.","Market basket","\ud83e\uddfa","transport_ticket")
B.F1=new A.cm([B.h0,B.ea,B.iG,B.iH],t.H4)
B.W_=s(["One ramen, please.","Is the ramen spicy?","The ramen was delicious."],t.s)
B.a0D=new A.dp("food_order","Order a favourite meal","Eating Out","I can order a dish and make a polite request.",B.eQ,B.F1,"\u30e9\u30fc\u30e1\u30f3\u3092\u4e00\u3064\u304a\u9858\u3044\u3057\u307e\u3059\u3002","Raamen o hitotsu onegaishimasu.","One ramen, please.",B.W_,0,"\u304a\u9858\u3044\u3057\u307e\u3059 is a flexible polite request. \u3054\u3061\u305d\u3046\u3055\u307e\u3067\u3057\u305f is a warm way to thank the meal afterward.","Sushi counter","\ud83c\udf63","shopping_price")
B.Xp=s(["Please call an ambulance.","Where is the hospital?","I have an appointment."],t.s)
B.a0v=new A.dp("emergency_help","Ask for urgent help","Emergencies","I can clearly ask someone to call an ambulance.",B.eQ,B.e9,"\u6551\u6025\u8eca\u3092\u547c\u3093\u3067\u304f\u3060\u3055\u3044\u3002","Kyuukyuusha o yonde kudasai.","Please call an ambulance.",B.Xp,0,"Japan\u2019s emergency number for ambulance and fire services is 119.","Safety lantern","\ud83c\udfee","food_order")
B.U1=s(["Could I leave a message?","May I use your phone?","Could you repeat that?"],t.s)
B.a0F=new A.dp("phone_message","Leave a telephone message","Telephoning","I can ask someone to leave a short message.",B.eQ,B.e9,"\u4f1d\u8a00\u3092\u304a\u9858\u3044\u3067\u304d\u307e\u3059\u304b\u3002","Dengon o onegai dekimasu ka?","Could I leave a message, please?",B.U1,0,"Business telephone calls commonly begin with a name and affiliation before the request.","Tiny telephone","\u260e\ufe0f","emergency_help")
